const fs = require('fs');

const diffContent = fs.readFileSync('/root/.local/share/opencode/tool-output/tool_f092d9ed60016YcShBJ5XEMgjo', 'utf8');
const lines = diffContent.split('\n');

let currentPackage = null;
let changes = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (line.startsWith('@@')) {
    currentPackage = null;
  }
  // If line identifies a yarn.lock package definition block in diff
  if (line.startsWith(' ') && !line.startsWith('  ') && (line.includes('@^') || line.includes('@~') || line.includes('@:')) && lines[i-1] && lines[i-1].startsWith('@@')) {
    currentPackage = line.trim().replace(/:$/, '');
  } else if ((line.startsWith('+') || line.startsWith('-')) && !line.startsWith('+++') && !line.startsWith('---') && !line.startsWith('+ ') && !line.startsWith('- ')) {
    // If we are in a block that starts with whitespace (like normal yarn.lock block header)
    // we can watch out for package definitions
    if (line.match(/^[\+-][\w\-@]+/)) {
      currentPackage = line.substring(1).trim().replace(/:$/, '');
    }
  }
  if (currentPackage && (line.startsWith('-  version "') || line.startsWith('+  version "'))) {
    changes.push({
      pkg: currentPackage,
      line: line
    });
  }
}

console.log(JSON.stringify(changes, null, 2));

