function runTest(testFile) {
  return new Promise((resolve, reject) => {
    const cmd = `yarn cross-env NODE_ENV=test jest --no-cache ${testFile}`;
    exec(cmd, (err, stdout, stderr) => {
      if (err) {
        reject({ testFile, stdout, stderr });
      } else {
        resolve({ testFile });
      }
    });
  });
}

async function start() {
  for (const test of remainingTests) {
    console.log(`Running: ${test}`);
    try {
      await runTest(test);
      console.log(`PASS: ${test}`);
    } catch (err) {
      console.error(`FAIL: ${err.testFile}\n--- STDERR ---\n${err.stderr}\n--- STDOUT ---\n${err.stdout}`);
      process.exit(1);
    }
  }
  console.log("ALL REMAINING TESTS PASSED!");
}

